#!/usr/bin/env bash
# The mldsa* and hash-mldsa* subcommands against the ACVP keyGen and Wycheproof verify known answers.
#
# Written for the 2026-11-03 CLI review (report 15) from the vector files named in each test;
# every expected value is copied from that file, none is typed by hand. Follows lib.sh's
# conventions: each test_* runs in its own subshell under `set -e`.

source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

# ACVP ML-DSA keyGen (bc-test-data/pqc/crypto/mldsa/ML-DSA-keyGen.txt, ML-DSA-44 tcId 1): the 32-byte
# seed xi gives the vector's sk (`keygen-from-seed`) and pk (`pk-from-sk`), from raw and hex seeds
# (hex needs --hex-input).
test_mldsa44_keygen_from_seed_matches_acvp() {
    local got
    unhex 61C5442C5C769EAC3021DCB9FFAB0D46223D456F0A72305E2F203DDD57BFFFCE >"$TMP/seed"
    got=$(hex_out "$BC_RUST" mldsa44 keygen-from-seed -x <"$TMP/seed")
    assert_eq "$got" "" "sk from a raw seed"
    got=$(printf '%s' 61C5442C5C769EAC3021DCB9FFAB0D46223D456F0A72305E2F203DDD57BFFFCE | hex_out "$BC_RUST" --hex-input mldsa44 keygen-from-seed -x)
    assert_eq "$got" "" "sk from a hex seed"
    "$BC_RUST" mldsa44 keygen-from-seed <"$TMP/seed" >"$TMP/sk"
    got=$(hex_out "$BC_RUST" mldsa44 pk-from-sk -x <"$TMP/sk")
    assert_eq "$got" "" "pk from the sk"
    expect_ok "the pair must be consistent" "$BC_RUST" mldsa44 check-consistency --pkfile <(unhex ) <"$TMP/sk" >/dev/null
    got=$(hex_out "$BC_RUST" hash-mldsa44 pk-from-sk -x <"$TMP/sk")
    assert_eq "$got" "" "hash-mldsa44 derives the same pk"
}

# Wycheproof testvectors_v1/mldsa_44_verify_test.json tcId 1 ("baseline", external interface, empty
# context) must verify, and tcId 6 ("short signature") must not. The signature and key are given as
# hex files (--hex-input) and as binary ones; the message "Hello world" is stdin either way.
test_mldsa44_verify_matches_wycheproof() {
    unhex 48656c6c6f20776f726c64 >"$TMP/msg"
    printf '%s'  >"$TMP/pk.hex"
    printf '%s'  >"$TMP/sig.hex"
    expect_ok "tcId 1 must verify" "$BC_RUST" --hex-input mldsa44 verify --pkfile "$TMP/pk.hex" --sigfile "$TMP/sig.hex" <"$TMP/msg" >/dev/null
    unhex  >"$TMP/pk.bin"; unhex  >"$TMP/sig.bin"
    expect_ok "tcId 1 must verify from binary files" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk.bin" --sigfile "$TMP/sig.bin" <"$TMP/msg" >/dev/null
    printf '%s'  >"$TMP/sig-bad.hex"
    expect_fail "tcId 6 must not verify" "$BC_RUST" --hex-input mldsa44 verify --pkfile "$TMP/pk.hex" --sigfile "$TMP/sig-bad.hex" <"$TMP/msg"
    assert_stderr_has "invalid"
    expect_fail "another message must not verify" "$BC_RUST" --hex-input mldsa44 verify --pkfile "$TMP/pk.hex" --sigfile "$TMP/sig.hex" < <(printf 'Hello World')
}

# Signing is randomized (FIPS 204 Alg 2 draws rnd), so there is no signature known answer; the
# round trip pins the wiring: sign with the sk, verify with the derived pk, with and without a
# context, in the pure and the HashML-DSA (SHA-512) forms, and each form rejects the other's
# signature and the other context.
test_mldsa44_sign_verify_round_trip() {
    "$BC_RUST" mldsa44 keygen >"$TMP/sk"
    assert_size "$TMP/sk" 2560 "sk length of ML-DSA-44"
    "$BC_RUST" mldsa44 pk-from-sk --skfile "$TMP/sk" >"$TMP/pk"
    rng 3000 >"$TMP/msg"
    "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" <"$TMP/msg" >"$TMP/sig"
    assert_size "$TMP/sig" 2420 "signature length of ML-DSA-44"
    expect_ok "pure signature verifies" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig" <"$TMP/msg" >/dev/null
    printf 'ctx' >"$TMP/ctx"
    expect_fail "a context the signer did not use must not verify" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig" --ctxfile "$TMP/ctx" <"$TMP/msg"
    "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" --ctxfile "$TMP/ctx" <"$TMP/msg" >"$TMP/sig-ctx"
    expect_ok "signature with context verifies with it" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-ctx" --ctxfile "$TMP/ctx" <"$TMP/msg" >/dev/null
    expect_fail "and not without it" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-ctx" <"$TMP/msg"
    "$BC_RUST" hash-mldsa44 sign --skfile "$TMP/sk" <"$TMP/msg" >"$TMP/sig-ph"
    expect_ok "HashML-DSA signature verifies as HashML-DSA" "$BC_RUST" hash-mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-ph" <"$TMP/msg" >/dev/null
    expect_fail "and not as pure ML-DSA" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-ph" <"$TMP/msg"
    expect_fail "nor the pure one as HashML-DSA" "$BC_RUST" hash-mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig" <"$TMP/msg"
}

