# FIPS 204 Alg 2 step 1: a context longer than 255 bytes is rejected. The CLI must report it
# (exit 255, an `Error:` line), not panic; and a seed of the wrong length likewise, for every
# parameter set and both forms.
test_bad_inputs_are_errors_not_panics() {
    local cmd
    head -c 256 /dev/zero >"$TMP/ctx256"
    head -c 255 /dev/zero >"$TMP/ctx255"
    rng 31 >"$TMP/seed31"
    for cmd in mldsa44 mldsa65 mldsa87 hash-mldsa44 hash-mldsa65 hash-mldsa87; do
        "$BC_RUST" $cmd keygen >"$TMP/sk"
        expect_ok "$cmd: a 255-byte context is allowed" "$BC_RUST" $cmd sign --skfile "$TMP/sk" --ctxfile "$TMP/ctx255" </dev/null >/dev/null
        expect_fail "$cmd: a 256-byte context" "$BC_RUST" $cmd sign --skfile "$TMP/sk" --ctxfile "$TMP/ctx256" </dev/null
        grep -q panicked "$LAST_STDERR" && fail "$cmd: ctx > 255 must not panic: $(head -1 "$LAST_STDERR")"
        assert_stderr_has "Error"
        expect_fail "$cmd: a 31-byte seed" "$BC_RUST" $cmd keygen-from-seed <"$TMP/seed31"
        grep -q panicked "$LAST_STDERR" && fail "$cmd: a bad seed must not panic: $(head -1 "$LAST_STDERR")"
        assert_stderr_has "Error"
    done
}

# A signature file of the wrong length, a truncated public key and a missing file are errors.
test_bad_files_are_errors() {
    "$BC_RUST" mldsa44 keygen >"$TMP/sk"
    "$BC_RUST" mldsa44 pk-from-sk --skfile "$TMP/sk" >"$TMP/pk"
    printf 'hello' | "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" >"$TMP/sig"
    head -c 100 "$TMP/sig" >"$TMP/sig-short"
    expect_fail "short signature" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-short" < <(printf 'hello')
    assert_stderr_has "invalid"
    head -c 100 "$TMP/pk" >"$TMP/pk-short"
    expect_fail "short pk" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk-short" --sigfile "$TMP/sig" < <(printf 'hello')
    assert_stderr_has "Error"
    expect_fail "missing sig file" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/nope" < <(printf 'hello')
    assert_stderr_has "Error"
}

# FIPS 204 Section 3.4: the deterministic variant signs with rnd all zero, so two signatures of
# one message agree, and it verifies like any other; the hedged default draws rnd, so two differ.
test_deterministic_signatures_repeat_and_hedged_ones_do_not() {
    "$BC_RUST" mldsa44 keygen >"$TMP/sk"
    "$BC_RUST" mldsa44 pk-from-sk --skfile "$TMP/sk" >"$TMP/pk"
    rng 100 >"$TMP/msg"
    "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" --deterministic <"$TMP/msg" >"$TMP/sig1"
    "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" --deterministic <"$TMP/msg" >"$TMP/sig2"
    assert_same "$TMP/sig1" "$TMP/sig2" "deterministic signatures must repeat"
    expect_ok "a deterministic signature verifies" "$BC_RUST" mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig1" <"$TMP/msg" >/dev/null
    "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" <"$TMP/msg" >"$TMP/sig3"
    "$BC_RUST" mldsa44 sign --skfile "$TMP/sk" <"$TMP/msg" >"$TMP/sig4"
    assert_differs "$TMP/sig3" "$TMP/sig4" "hedged signatures must differ"
    "$BC_RUST" hash-mldsa44 sign --skfile "$TMP/sk" --deterministic <"$TMP/msg" >"$TMP/sig5"
    "$BC_RUST" hash-mldsa44 sign --skfile "$TMP/sk" --deterministic <"$TMP/msg" >"$TMP/sig6"
    assert_same "$TMP/sig5" "$TMP/sig6" "deterministic HashML-DSA signatures must repeat"
}

# The external-mu interface: compute-mu gives the 64-byte representative of FIPS 204 Algorithm 7
# line 6, sign-mu signs it, and the result verifies both as an ordinary signature over the message
# and with verify-mu; a context is part of mu, so the wrong one fails.
test_external_mu_round_trip() {
    "$BC_RUST" mldsa65 keygen >"$TMP/sk"
    "$BC_RUST" mldsa65 pk-from-sk --skfile "$TMP/sk" >"$TMP/pk"
    rng 1000 >"$TMP/msg"
    printf 'ctx' >"$TMP/ctx"
    "$BC_RUST" mldsa65 compute-mu --pkfile "$TMP/pk" --ctxfile "$TMP/ctx" <"$TMP/msg" >"$TMP/mu"
    assert_size "$TMP/mu" 64 "mu length"
    "$BC_RUST" mldsa65 sign-mu --skfile "$TMP/sk" --mufile "$TMP/mu" </dev/null >"$TMP/sig"
    assert_size "$TMP/sig" 3309 "signature length of ML-DSA-65"
    expect_ok "a mu signature verifies over the message" "$BC_RUST" mldsa65 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig" --ctxfile "$TMP/ctx" <"$TMP/msg" >/dev/null
    expect_ok "and with verify-mu" "$BC_RUST" mldsa65 verify-mu --pkfile "$TMP/pk" --sigfile "$TMP/sig" <"$TMP/mu" >/dev/null
    expect_fail "not under another context" "$BC_RUST" mldsa65 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig" <"$TMP/msg"
    "$BC_RUST" mldsa65 sign-mu --skfile "$TMP/sk" --deterministic <"$TMP/mu" >"$TMP/sig-det"
    expect_ok "a deterministic mu signature verifies" "$BC_RUST" mldsa65 verify-mu --pkfile "$TMP/pk" --sigfile "$TMP/sig-det" --mufile "$TMP/mu" </dev/null >/dev/null
    expect_fail "mu is 64 bytes" "$BC_RUST" mldsa65 sign-mu --skfile "$TMP/sk" < <(rng 63)
    assert_stderr_has "64 bytes"
    expect_fail "the mu actions are not HashML-DSA's" "$BC_RUST" hash-mldsa65 compute-mu --pkfile "$TMP/pk" <"$TMP/msg"
    assert_stderr_has "hash-mldsa"
}

# FIPS 204 Section 5.4: the pre-hash must be at least as strong as the parameter set. --hash
# selects it; sha256 and shake128 (RFC 8702's 32-byte digest) fit hash-mldsa44 only, sha512 and
# shake256 fit all three, and a signature only verifies under the hash it was made with.
test_hash_mldsa_pre_hash_choice() {
    local h
    "$BC_RUST" mldsa44 keygen >"$TMP/sk"
    "$BC_RUST" mldsa44 pk-from-sk --skfile "$TMP/sk" >"$TMP/pk"
    rng 500 >"$TMP/msg"
    for h in sha256 sha512 shake128 shake256; do
        "$BC_RUST" hash-mldsa44 sign --skfile "$TMP/sk" --hash $h <"$TMP/msg" >"$TMP/sig-$h"
        expect_ok "hash-mldsa44 with $h verifies" "$BC_RUST" hash-mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-$h" --hash $h <"$TMP/msg" >/dev/null
    done
    expect_fail "a sha256 signature is not a sha512 one" "$BC_RUST" hash-mldsa44 verify --pkfile "$TMP/pk" --sigfile "$TMP/sig-sha256" <"$TMP/msg"
    "$BC_RUST" mldsa65 keygen >"$TMP/sk65"
    "$BC_RUST" mldsa65 pk-from-sk --skfile "$TMP/sk65" >"$TMP/pk65"
    for h in sha256 shake128; do
        expect_fail "hash-mldsa65 refuses $h" "$BC_RUST" hash-mldsa65 sign --skfile "$TMP/sk65" --hash $h <"$TMP/msg"
        assert_stderr_has "PreHashTooWeak"
        expect_fail "and on verify" "$BC_RUST" hash-mldsa65 verify --pkfile "$TMP/pk65" --sigfile "$TMP/sig-sha256" --hash $h <"$TMP/msg"
        assert_stderr_has "PreHashTooWeak"
    done
    "$BC_RUST" hash-mldsa65 sign --skfile "$TMP/sk65" --hash shake256 <"$TMP/msg" >"$TMP/sig65"
    expect_ok "hash-mldsa65 with shake256 verifies" "$BC_RUST" hash-mldsa65 verify --pkfile "$TMP/pk65" --sigfile "$TMP/sig65" --hash shake256 <"$TMP/msg" >/dev/null
}

run_all
